 leaves.append({'id':id,'status':status,'original_requirement':requirements[id],'findings':finding,'source_references':sources,'test_references':testrefs,'evidence':evidence,'checks_performed':['Read full original leaf and cited source/assertions','Compare scoped input hashes with FA-02; see input-evidence.json','Reconcile retained reports without rerunning passed suites'],'head':e['head'],'input_limits':limits or 'Unchanged selected inputs retain FA-04 aggregate unit evidence. No new runtime/native/device/AT result. Full transitive host/build equivalence is not established.','host_limits':'Modified shared dev checkout; no shared outputs rebuilt. Concurrent BUG-0008/0009 changes are excluded from old-output acceptance.','successor_deliverables':successor})
